<?php
declare(strict_types=1);
putenv('APP_ENV=demo');
$external=getenv('TEST_DB_DSN');putenv('DB_DSN='.($external?:'sqlite::memory:'));if(getenv('TEST_DB_USER'))putenv('DB_USER='.getenv('TEST_DB_USER'));
require __DIR__.'/../src/bootstrap.php';
$passed=0;$failed=0;$cases=[];
function check(string $name,callable $fn):void{global $passed,$failed,$cases;try{$fn();$passed++;$cases[]=['test'=>$name,'status'=>'pass'];}catch(Throwable $e){$failed++;$cases[]=['test'=>$name,'status'=>'fail','error'=>$e->getMessage()];}}
function eq(mixed $a,mixed $b,string $why='Values differ'):void{if($a!==$b)throw new RuntimeException($why.' '.json_encode([$a,$b]));}
function denies(callable $fn,int $status):void{try{$fn();}catch(HttpError $e){eq($e->status,$status);return;}throw new RuntimeException('Expected denied operation.');}
$nonce=bin2hex(random_bytes(5));$_SERVER['REMOTE_ADDR']='test-'.$nonce;
check('Database catalog is populated and search is parameterized',function()use($store){$c=$store->catalog(['q'=>'Acer','limit'=>100]);if($c['total']<1)throw new RuntimeException('Missing source products');eq($store->catalog(['q'=>"' OR 1=1 --"])['total'],0);});
check('Categories and prices are filtered',function()use($store){foreach($store->catalog(['category'=>'laptops','max'=>10000])['products'] as $p){eq($p['category_slug'],'laptops');if($p['price_cents']>1000000)throw new RuntimeException('Price filter failed');}});
check('CSRF denies missing and invalid tokens',function()use($store){denies(fn()=>$store->csrf(null),419);denies(fn()=>$store->csrf('bad'),419);$store->csrf($store->session()['csrf']);});
check('Guest cannot read administrative or account data',function()use($store){denies(fn()=>$store->dashboard(),401);denies(fn()=>$store->account(),401);});
$products=$store->catalog(['stock'=>1,'limit'=>2])['products'];$p=$products[0];
check('Cart totals use server price, reject stock overrun, allow removal',function()use($store,$p){$c=$store->updateCart(['variant_id'=>$p['variant_id'],'quantity'=>2,'price_cents'=>1]);eq($c['total_cents'],$p['price_cents']*2);denies(fn()=>$store->updateCart(['variant_id'=>$p['variant_id'],'quantity'=>99]),409);$store->updateCart(['variant_id'=>$p['variant_id'],'quantity'=>0]);eq($store->cart()['count'],0);});
check('Registration ignores role escalation fields',function()use($store,$nonce){$s=$store->register(['name'=>'Test customer','email'=>'customer-'.$nonce.'@example.test','password'=>'A-long-test-password-42','role'=>'super_admin']);eq($s['user']['role'],'customer');denies(fn()=>$store->dashboard(),403);});
$userId=(int)$store->user()['id'];
check('Dealer application stays pending until admin approval',function()use($store){$a=$store->applyDealer(['business_name'=>'Test-only business','registration_number'=>'TEST','contact_name'=>'Test customer','phone'=>'000','address'=>'Test-only address']);eq($a['application']['status'],'pending');eq($store->user()['role'],'pending_dealer');});
$dealerId=(int)$store->db->one('SELECT id FROM dealer_applications WHERE user_id=?',[$userId])['id'];
$adminId=$store->db->insert('users',['name'=>'Test administrator','email'=>'admin-'.$nonce.'@example.test','password_hash'=>password_hash('admin-test-long-password',PASSWORD_DEFAULT),'role'=>'admin','created_at'=>gmdate('c')]);
check('Only admin approves dealer and applies server-side dealer pricing',function()use($store,$adminId,$dealerId,$userId,$p){denies(fn()=>$store->adminDealer(['id'=>$dealerId,'status'=>'approved']),403);$_SESSION['user_id']=$adminId;$_SESSION['auth_fingerprint']=hash('sha256',$store->db->one('SELECT password_hash FROM users WHERE id=?',[$adminId] )['password_hash']);$store->adminDealer(['id'=>$dealerId,'status'=>'approved']);$store->db->run('UPDATE product_variants SET dealer_price_cents=? WHERE id=?',[$p['price_cents']-100,$p['variant_id']]);$_SESSION['user_id']=$userId;$_SESSION['auth_fingerprint']=hash('sha256',$store->db->one('SELECT password_hash FROM users WHERE id=?',[$userId] )['password_hash']);eq($store->user()['role'],'dealer');eq($store->variant($p['variant_id'])['price_cents'],$p['price_cents']-100);});
$checkout=['idempotency_key'=>'test-order-'.$nonce.'-001','name'=>'Test customer','email'=>'customer-'.$nonce.'@example.test','phone'=>'000','address'=>'Test address','city'=>'Test city','postal_code'=>'0000','payment_method'=>'eft','delivery'=>'quote'];
check('Dealer cannot bypass EFT-only checkout',function()use($store,$checkout){$d=$checkout;$d['payment_method']='payfast';denies(fn()=>$store->checkout($d),403);});
$order=null;
check('Checkout creates one immutable order and repeats idempotently',function()use($store,$p,$checkout,&$order){$store->updateCart(['variant_id'=>$p['variant_id'],'quantity'=>1]);$price=$store->variant($p['variant_id'])['price_cents'];$stock=$store->variant($p['variant_id'])['stock'];$order=$store->checkout($checkout)['order'];eq((int)$order['total_cents'],$price);eq($order['status'],'pending_payment');eq((int)$order['is_demo'],1);eq($store->variant($p['variant_id'])['stock'],$stock-1);eq($store->checkout($checkout)['order']['id'],$order['id']);eq($store->variant($p['variant_id'])['stock'],$stock-1);eq($store->cart()['count'],0);});
check('Stock race at checkout rolls back instead of overselling',function()use($store,$products,$checkout){$p=$products[1];$store->updateCart(['variant_id'=>$p['variant_id'],'quantity'=>1]);$store->db->run('UPDATE product_variants SET stock=0 WHERE id=?',[$p['variant_id']]);$d=$checkout;$d['idempotency_key'].='-soldout';denies(fn()=>$store->checkout($d),409);eq($store->variant($p['variant_id'])['stock'],0);$store->updateCart(['variant_id'=>$p['variant_id'],'quantity'=>0]);});
check('Quote captures totals and provides a protected valid PDF',function()use($store,$p){$store->updateCart(['variant_id'=>$p['variant_id'],'quantity'=>1]);$q=$store->createQuote(['source'=>'cart']);$pdf=$store->quotePdf($q['id']);if(!str_starts_with($pdf,'%PDF-1.4')||!str_contains($pdf,'%%EOF'))throw new RuntimeException('Invalid PDF');});
$groups=$store->buildOptions()['groups'];$components=[];foreach($groups as $g=>$list){if($list)$components[$g]=$list[0]['variant_id'];}
check('Builder returns every group, computes costs and flags unknown BIOS',function()use($store,$components){eq(count($components),8);$b=$store->validateBuild($components);eq($b['warnings'],[]);eq($b['status'],'needs_review');if($b['estimated_watts']<200||!$b['missing'])throw new RuntimeException('Missing compatibility information');});
check('Builder detects socket and DDR mismatch and refuses cart conversion',function()use($store,$components,$groups){$bad=$components;$bad['motherboard']=$groups['motherboard'][1]['variant_id'];$b=$store->validateBuild($bad);if(count($b['warnings'])<2)throw new RuntimeException('Mismatch not detected');denies(fn()=>$store->buildCart(['components'=>$bad]),409);});
check('Saved build is durable and shareable without customer data',function()use($store,$components){$b=$store->saveBuild(['name'=>'Test build','purpose'=>'gaming','components'=>$components]);$shared=$store->sharedBuild($b['share_token']);eq(count($shared['components']),8);if(isset($shared['user_id']))throw new RuntimeException('Customer information leaked');});
$ticket=null;
check('Ticket history and reply are persisted',function()use($store,&$ticket){$ticket=$store->createTicket(['subject'=>'Test issue','category'=>'technical','message'=>'Test message']);$t=$store->replyTicket($ticket['id'],['message'=>'More information']);eq(count($t['messages']),2);});
check('Ownership boundaries protect order and ticket data',function()use($store,$order,$ticket,$nonce,$userId){$store->logout();$store->register(['name'=>'Another test user','email'=>'other-'.$nonce.'@example.test','password'=>'A-long-test-password-42']);denies(fn()=>$store->order((int)$order['id']),404);denies(fn()=>$store->ticket((int)$ticket['id']),404);$_SESSION['user_id']=$userId;$_SESSION['auth_fingerprint']=hash('sha256',$store->db->one('SELECT password_hash FROM users WHERE id=?',[$userId] )['password_hash']);});
check('Cart expiration deletes cart items but preserves orders',function()use($store,$p){$store->updateCart(['variant_id'=>$p['variant_id'],'quantity'=>1]);$before=(int)$store->db->run('SELECT COUNT(*) FROM orders')->fetchColumn();$store->db->run('UPDATE carts SET updated_at=? WHERE token=?',[gmdate('c',time()-90000),$_SESSION['guest_token']]);eq($store->cart()['count'],0);eq((int)$store->db->run('SELECT COUNT(*) FROM orders')->fetchColumn(),$before);});
check('Marketing unsubscribe is stored and account email cannot be overridden',function()use($store){$email=$store->user()['email'];$store->consent(['email'=>'victim@example.test','consent'=>true]);eq((int)$store->db->one('SELECT consent FROM marketing_consents WHERE email=?',[$email])['consent'],1);$store->consent(['consent'=>false]);eq((int)$store->db->one('SELECT consent FROM marketing_consents WHERE email=?',[$email])['consent'],0);});
check('Payment validation amount mismatch is rejected and replay is idempotent',function()use($store,$order){$store->db->run("UPDATE orders SET payment_method='payfast' WHERE id=?",[$order['id']]);$event=['provider_id'=>'test-payment-'.$order['id'],'order_id'=>$order['id'],'amount_cents'=>(int)$order['total_cents'],'status'=>'complete'];$bad=$event;$bad['amount_cents']--;denies(fn()=>$store->recordVerifiedPayment($bad),400);eq($store->recordVerifiedPayment($event)['duplicate'],false);eq($store->recordVerifiedPayment($event)['duplicate'],true);});
check('Production checkout fails closed without operational verification',function()use($store,$checkout){$store->demo=false;$d=$checkout;$d['idempotency_key'].='-production';denies(fn()=>$store->checkout($d),503);$store->demo=true;});
check('Admin state transitions require reasons and correct previous state',function()use($store,$adminId,$order){$_SESSION['user_id']=$adminId;$_SESSION['auth_fingerprint']=hash('sha256',$store->db->one('SELECT password_hash FROM users WHERE id=?',[$adminId] )['password_hash']);denies(fn()=>$store->adminOrder(['id'=>$order['id'],'status'=>'delivered','reason'=>'Test']),409);$o=$store->adminOrder(['id'=>$order['id'],'status'=>'processing','reason'=>'Verified test order']);eq($o['status'],'processing');});
check('Failed login has generic response and session does not gain authority',function()use($store,$nonce){$store->logout();denies(fn()=>$store->login(['email'=>'absent-'.$nonce.'@example.test','password'=>'wrong']),401);eq($store->user(),null);});
check('Rate limits block repeated requests',function()use($store,$nonce){$store->limit('test-limit-'.$nonce,2,100);$store->limit('test-limit-'.$nonce,2,100);denies(fn()=>$store->limit('test-limit-'.$nonce,2,100),429);});
echo json_encode(['database'=>$external?'mysql':'sqlite','passed'=>$passed,'failed'=>$failed,'cases'=>$cases],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)."\n";exit($failed?1:0);
